// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='62'); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='22'); } }, { id: "slc_prtdepoRsnCd", fn: function(){ return ((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'); } }, { id: "slc_prtdepoRsnMngrghtTpCd", fn: function(){ return ((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'); } }, { id: "c_otherwise_114", fn: function(){ return (!(((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'))); } }, { id: "if_corpUsrTpCd_3", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='22'); } }, { id: "btn_delete", fn: function(){ return (! (String(((dma_PrePrtDepo.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "PrePrtDepo.prtdepoId"); })())) == null ? '' : ((dma_PrePrtDepo.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "PrePrtDepo.prtdepoId"); })()))).length === 0)); } }, { id: "btn_cancel", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "completeYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("completeYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "completeYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("completeYn")))).length === 0)); } }, { id: "c_otherwise_169", fn: function(){ return (!(((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "completeYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("completeYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "completeYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("completeYn")))).length === 0)))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.onload();
        try {
            if (form.prtdepoShrsDsp.value == null) {
                for (let i = 0; i < form.prtdepoShrsDsp.length; i++) {
                    fn_ObjValueSetComma(form.prtdepoShrsDsp[i]);
                }
            } else {
                fn_ObjValueSetComma(form.prtdepoShrsDsp);
            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldfil55220' }); return; }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55220.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil55220.onpageload' });
    }
};


