    if ($c.util.getComponent('slc_prtdepoObjTpCd').getValue()=== "6") {
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(false);
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue("");
        $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onChangeObjRsnCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onChangeObjRsnCd = function () {
    /* sdd-asis-lifecycle:begin fn_OnChangeObjRsnCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ('' + dma_basicComInfo.get("mktTpCd") + '' === "1") {
        if ($c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "19") {
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(true);
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
        } else {
            if (($c.util.getComponent('slc_prtdepoRsnCd').getValue() == null ? '' : String($c.util.getComponent('slc_prtdepoRsnCd').getValue())) === '') {
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(false);
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(false);
            } else {
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(false);
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
                $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
            }
        }
    } else {
        if ($c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "69" || $c.util.getComponent('slc_prtdepoRsnCd').getValue()=== "70" || ($c.util.getComponent('slc_prtdepoRsnCd').getValue() == null ? '' : String($c.util.getComponent('slc_prtdepoRsnCd').getValue())) === '') {
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setDisabled(true);
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setValue("");
            $c.util.getComponent('slc_prtdepoRsnFncTpCd').setDisabled(true);
        } else {
            $c.util.getComponent('slc_prtdepoRsnMngrghtTpCd').setValue("");
