/**
 * @method
 * @name scwin.checkDate
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.checkDate = async function (obj) {
/* sdd-asis-lifecycle:begin fn_CheckDate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


	if (obj.getValue().length == 0)
		return true;

	obj.setValue(scwin.removeChar(obj.getValue(), '-'));
	obj.setValue(scwin.removeChar(obj.getValue(), '/'));

	if (obj.getValue().length != 8){
		await $c.win.alert ( ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날짜는 8 자리 YYYYMMDD 형식입니다.');
		obj.focus();
		return false;
	}

	if ( (obj.getValue() == null ? '' : String(obj.getValue())) != '' && !scwin.isMinusNum(obj.getValue()) )
	{
		await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + "숫자만 입력가능합니다.");
		obj.focus();
		return false;
	}

	const year = obj.getValue().substring(0, 4);
	const month = obj.getValue().substring(4, 6);
	const day = obj.getValue().substring(6, 8);

	if (month > 12 || month < 1)
	{
		await $c.win.alert (((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '달은 1 에서 12 사이여야 합니다.');
		obj.focus();
		return false;
	} 

	//날짜 값 체크 수정
	if (month == 1) total_days = 31;
	else if (month == 2) {
		if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0))
			total_days = 29;
		else
			total_days = 28;
	}
	else if (month == 3) total_days = 31;
	else if (month == 4) total_days = 30;
	else if (month == 5) total_days = 31;
	else if (month == 6) total_days = 30;
	else if (month == 7) total_days = 31;
	else if (month == 8) total_days = 31;
	else if (month == 9) total_days = 30;
	else if (month == 10) total_days = 31;
	else if (month == 11) total_days = 30;
	else if (month == 12) total_days = 31;	

	if (day > total_days || day < 1) {
	  await $c.win.alert (((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + " 존재하지 않는 날짜입니다.");
		obj.focus();
		return false;
	}

	return true;		

/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.removeChar
 * @author Inswave
 * @date 2026. 09. 29
 * @param org ch
 * @returns
 * @hidden N
*/
scwin.removeChar = function (org, ch) {
/* sdd-asis-lifecycle:begin removeChar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

	const len = org.length;
	let returnStr = '';

	for (i=0; i<len; i++){
		if (org.charAt(i) == ch)
			continue;
		returnStr += org.charAt(i);
	}

	return returnStr;
/* sdd-asis-lifecycle:end */
};


